{
  "requirement_id": "REQ-007",
  "summary": "專案、任務列表及任務詳情 API 的讀取權限控制，僅限專案成員存取，非成員回傳 403，資源不存在回傳 404。",
  "acceptance_criteria": [
    "專案、任務列表與任務詳情（GET /api/tasks/{tid}）僅限該專案成員讀取",
    "非專案成員存取時回傳 403 Forbidden",
    "請求的資源不存在時回傳 404 Not Found"
  ]
}

