{
  "requirement_id": "REQ-007",
  "cases": [
    {
      "id": "TC-1",
      "title": "Project member can read task detail",
      "surface": "api",
      "steps": [
        "Alice creates a project and a task within it",
        "Alice sends GET /api/tasks/{tid} with header X-User: alice"
      ],
      "expected": "專案、任務列表與任務詳情（GET /api/tasks/{tid}）僅限該專案成員讀取"
    },
    {
      "id": "TC-2",
      "title": "Non-project member is forbidden from reading task detail",
      "surface": "api",
      "steps": [
        "Alice creates a project and a task within it",
        "Bob (who is not a member of Alice's project) sends GET /api/tasks/{tid} with header X-User: bob"
      ],
      "expected": "非專案成員存取時回傳 403 Forbidden"
    },
    {
      "id": "TC-3",
      "title": "Requesting a non-existent task returns 404",
      "surface": "api",
      "steps": [
        "Alice sends GET /api/tasks/99999 with header X-User: alice"
      ],
      "expected": "請求的資源不存在時回傳 404 Not Found"
    }
  ]
}

